begin;
set local lock_timeout = '10s';
set local statement_timeout = '60s';

-- Additive: missing dataset continues to mean Okinawa, preserving old clients and IDs.
alter table public.regions add column osm_dataset text;
alter table public.regions add constraint regions_osm_dataset_check
  check (osm_dataset is null or (map_provider='osm' and osm_dataset in ('okinawa','taiwan')));

-- Same rings as shared/geo/osm-datasets.json. Extraction coverage is deliberately
-- explicit; never accept arbitrary coordinates in the enclosing bounding box.
create function public.app_osm_contains(dataset text, latitude numeric, longitude numeric)
returns boolean language plpgsql immutable set search_path='' as $$
declare rings jsonb; ring jsonb; a jsonb; b jsonb; i integer; hit boolean;
  ax numeric; ay numeric; bx numeric; by_ numeric; cross_value numeric;
begin
  if latitude is null or longitude is null or latitude not between -90 and 90 or longitude not between -180 and 180 then return false; end if;
